/* The page, built from the run in data.js.
 *
 * Three rules this file follows:
 *
 *   1. No number is written here. Every figure comes from `M`, generated by
 *      tools/render_results.py from results/run.json. Exercise 09 shipped a document claiming
 *      every figure was generated while fifteen were typed inside the renderer; a page is the
 *      version of that failure the most people see.
 *   2. A mechanism figure is not a results chart. The accumulation bug is the central object here,
 *      so the page draws the two reductions side by side with their real weights — results say what
 *      happened, mechanism says why it must.
 *   3. A failure goes in the opening tiles. This page has three to choose from and it leads with
 *      the worst one.
 *
 * Sections carry `data-role`, so the spine is checkable without pinning any wording.
 */

const NS = 'http://www.w3.org/2000/svg';
const main = () => document.getElementById('main');

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text !== undefined) n.textContent = text;
  return n;
}

function svg(tag, attrs = {}) {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
  return n;
}

function svgText(x, y, cls, text) {
  const t = svg('text', { x, y, class: cls });
  t.textContent = text;
  return t;
}

let sectionCount = 0;

/** A section whose eyebrow names its epistemic role, so a reader knows how to weigh it. */
function section(id, role, eyebrow, title, paras, rail) {
  const s = el('section');
  s.id = id;
  s.dataset.role = role;
  sectionCount += 1;
  s.dataset.n = String(sectionCount);
  s.dataset.title = (rail && rail.short) || title;
  if (rail && rail.sub) s.dataset.sub = rail.sub;
  s.append(el('p', 'role', eyebrow), el('h2', null, title));
  for (const p of [].concat(paras || [])) {
    const n = el('p', 'say');
    n.innerHTML = p;
    s.append(n);
  }
  main().append(s);
  return s;
}

/** A figure whose caption says what to conclude — never a bare label. */
function figure(node, num, caption) {
  const f = el('figure');
  f.append(node);
  const c = el('figcaption');
  c.innerHTML = `<b>Figure ${num}.</b> ${caption}`;
  f.append(c);
  return f;
}

function table(head, rows, cls) {
  const wrap = el('div', 'tablewrap');
  const t = el('table', cls || 'grid');
  const thead = el('thead');
  const hr = el('tr');
  for (const h of head) {
    const th = el('th');
    th.innerHTML = h;
    hr.append(th);
  }
  thead.append(hr);
  t.append(thead);
  const tb = el('tbody');
  for (const row of rows) {
    const tr = el('tr');
    if (row.__mark) tr.className = row.__mark;
    for (const cell of row.cells) {
      const td = el('td');
      td.innerHTML = cell === null || cell === undefined ? '—' : cell;
      tr.append(td);
    }
    tb.append(tr);
  }
  t.append(tb);
  wrap.append(t);
  return wrap;
}

const int = (n) => Math.round(n).toLocaleString('en-US');
const signed = (n, d = 4) => (n >= 0 ? '+' : '−') + Math.abs(n).toFixed(d);
const pct = (n, d = 1) => `${(n * 100).toFixed(d)}%`;

/* ============================================================== 1 · thesis */

function chapterThesis(M) {
  const five = M.item_5_mfu;
  const two = M.item_2_gradient;
  const three = M.item_3_accumulation;
  const s = section(
    'thesis',
    'thesis',
    'The claim',
    'Every number here had to be argued with first',
    [
      `Six checks on a real training loop, and <b>not one of them rewards a low loss</b>. Each is a
       measurement of the loop or a deliberate breakage of it.`,
      `Three of the numbers below were wrong before they were right, and none of the three was
       caught by a failing test. <b>Two were flattering themselves</b> — one in the denominator of a
       ratio, one in its numerator — and the third was a bug in code whose test passed because it
       drove exactly one value.`,
    ],
    { short: 'The claim', sub: 'three numbers argued with' }
  );

  const tiles = el('div', 'tiles');
  for (const [v, k, mark] of [
    [
      '30%',
      'of fp8 inputs came back <b>exactly twice too large</b> from a function whose test passed',
      'bad',
    ],
    [
      pct(five.mfu, 2),
      `utilisation — after a first answer of 39.13% that divided one processor's work by another's capability`,
      'bad',
    ],
    [
      `${two.best_matching_digits.toFixed(1)}`,
      'decimal digits where autograd and hand-computed arithmetic agree, at the best nudge size',
      'good',
    ],
    [
      pct(three.relative_gap),
      'wrong, from a reduction that looks right and is exactly correct whenever you test it casually',
      'good',
    ],
  ]) {
    const tile = el('div', `tile ${mark}`);
    const value = el('div', 'tile-v');
    value.innerHTML = v;
    const key = el('div', 'tile-k');
    key.innerHTML = k;
    tile.append(value, key);
    tiles.append(tile);
  }
  s.append(tiles);

  const note = el('p', 'say small');
  note.innerHTML = `The first two tiles are failures of this page's own work, and they are first
    deliberately. A page that shows only its wins has not earned the ones it shows — and both of
    these were found by asking what a number was actually counting, which is the only technique on
    offer here.`;
  s.append(note);
}

/* ============================================================== 2 · glossary */

function chapterGlossary(M) {
  const facts = M.facts;
  const s = section(
    'glossary',
    'glossary',
    'Vocabulary',
    'Nine words, each with a number from this run',
    [
      `Read this once and nothing below is jargon. Every entry carries a real figure from the run on
       this page rather than a textbook gloss.`,
    ],
    { short: 'Vocabulary', sub: 'nine words, defined once' }
  );

  const entries = [
    [
      'the loss',
      `One number saying how wrong the model's guesses were. Lower is better, and <i>training</i> is
       the process of nudging the model's numbers to make it smaller. This run takes
       ${int(facts.steps)} such nudges.`,
    ],
    [
      'a step',
      `One nudge: read a batch of text, score it, work out which direction each number should move,
       move it. Everything on this page is about a single one of those.`,
    ],
    [
      'the trunk and the head',
      `The model splits in two. The <b>trunk</b> turns text into a vector per position
       (${int(facts.trunk_parameters)} numbers); the <b>head</b> turns each vector into a score for
       every token (${int(facts.head_parameters)}). The split decides which parameters get priced
       in the utilisation figure.`,
    ],
    [
      'a gradient',
      `How much the loss would move if one number moved. <code>backward()</code> computes them all
       at once — and a gradient is a <i>claim</i>, so it can be checked by moving the number and
       looking.`,
    ],
    [
      'the gradient norm',
      `All the gradients as one number: how hard the optimiser is pushing right now. Unlike the
       loss it is not an average over a batch, which is why it moves first.`,
    ],
    [
      'a micro-batch',
      `When the batch you want will not fit in memory, you split it. Each piece is a micro-batch,
       and combining their losses correctly is <a href="#mechanism">the whole of section 4</a>.`,
    ],
    [
      'clipping',
      `Capping the gradient's size so one strange batch cannot throw the model. This run clips at
       ${facts.grad_clip} — and logs the norm <b>before</b> clipping, because a post-clip trace
       flattens at the cap and hides the spikes it exists to show.`,
    ],
    [
      'FLOPs',
      `Floating-point operations — a count of arithmetic. Used here to ask what fraction of the
       machine's capability the run actually used.`,
    ],
    [
      'exponent and mantissa',
      `How a float divides its bits: the <b>exponent</b> fixes the magnitude, the <b>mantissa</b>
       picks the value within it. Exponent bits buy range, mantissa bits buy precision, and more of
       one is always less of the other.`,
    ],
  ];
  const dl = el('dl', 'gloss');
  for (const [term, def] of entries) {
    dl.append(el('dt', null, term));
    const dd = el('dd');
    dd.innerHTML = def;
    dl.append(dd);
  }
  s.append(dl);
}

