/* ============================================================== 4 · mechanism */

function accumulationFigure(M) {
  const three = M.item_3_accumulation;
  const counts = three.token_counts;
  const losses = three.losses;
  const n = counts.length;

  const w = 640;
  const h = 300;
  const pad = 24;
  /* A gutter the bars never enter, because the sum labels live in it. The first version let the
   * bars run the full width and "= 3.0000" was drawn straight through the third one. */
  const gutter = 96;
  const colw = (w - pad * 2 - gutter) / n;
  const maxTokens = Math.max(...counts);

  const node = svg('svg', {
    viewBox: `0 0 ${w} ${h}`,
    class: 'fig accfig',
    role: 'img',
    'aria-label':
      'Three micro-batches of different sizes, and the two ways of combining their losses — one ' +
      'weighting each by its token count, one giving all three an equal vote',
  });

  node.append(svgText(pad, 22, 'fig-lab', 'three micro-batches, different sizes'));

  counts.forEach((tokens, i) => {
    const x = pad + i * colw;
    const bw = colw - 16;
    /* Width is proportional to the token count, so the short micro-batch LOOKS short. That is the
     * whole mechanism: the wrong reduction gives this narrow box the same vote as the wide ones. */
    const scaled = bw * (tokens / maxTokens);
    node.append(
      svg('rect', { x, y: 36, width: scaled, height: 44, rx: 6, class: 'acc-box' }),
      svgText(x + scaled / 2, 63, 'acc-t', `${tokens} tokens`),
      svgText(x + scaled / 2, 98, 'acc-loss', `loss ${losses[i].toFixed(1)}`)
    );
  });

  node.append(svgText(pad, 140, 'fig-lab', 'correct — every token weighs the same'));
  counts.forEach((tokens, i) => {
    const x = pad + i * colw;
    const bw = (colw - 16) * (tokens / maxTokens);
    node.append(svg('rect', { x, y: 150, width: bw, height: 18, rx: 4, class: 'acc-vote good' }));
  });
  node.append(svgText(w - pad, 164, 'acc-sum end good', `= ${three.correct.toFixed(4)}`));

  node.append(svgText(pad, 206, 'fig-lab', 'wrong — every micro-batch weighs the same'));
  counts.forEach((_, i) => {
    const x = pad + i * colw;
    node.append(
      svg('rect', { x, y: 216, width: colw - 16, height: 18, rx: 4, class: 'acc-vote bad' })
    );
  });
  node.append(svgText(w - pad, 230, 'acc-sum end bad', `= ${three.wrong.toFixed(4)}`));

  node.append(
    svgText(pad, 272, 'acc-gap', `the short batch gets a full vote  →  ${pct(three.relative_gap)} wrong`)
  );

  return node;
}

function chapterMechanism(M) {
  const three = M.item_3_accumulation;
  const s = section(
    'mechanism',
    'mechanism',
    'How it works',
    'Averaging the averages, and why it hid for years',
    [
      `When the batch you want will not fit in memory, you split it into micro-batches, combine
       their losses, and take one step. <b>The combination has to weight each piece by how many real
       tokens it holds.</b>`,
      `Averaging the averages instead gives a micro-batch with ${Math.min(...three.token_counts)}
       tokens exactly the same vote as one with ${Math.max(...three.token_counts)}. On the three
       below that is <b>${pct(three.relative_gap)}</b> wrong.`,
    ],
    { short: 'How it works', sub: 'the bug, drawn' }
  );

  s.append(
    figure(
      accumulationFigure(M),
      1,
      `Each bar's width is its real token count, so the short micro-batch <i>looks</i> short. In the
       correct reduction the bars keep those widths; in the wrong one they are all made equal, and
       the narrow one is handed a vote it did not earn. <b>The error is exactly zero when the three
       bars are already the same width</b> — which is what a hand-built test case almost always
       looks like, and why a bug of this shape lived inside every major training framework until
       2024.`
    )
  );

  const note = el('p', 'say');
  note.innerHTML = `That last sentence is the reason this exercise's configuration is uneven
    <b>by decision</b>, and why the comparison <b>refuses</b> an even one rather than returning a
    gap of zero. A zero here would say the experiment was blind, not that the code is right.`;
  s.append(note);
}

