/* ============================================================== 7 · results */

function sweepFigure(M) {
  const sweep = M.item_2_gradient.sweep;
  const w = 660;
  const h = 300;
  const padL = 54;
  const padB = 46;
  const padT = 34;
  const padR = 20;

  const digits = sweep.map((r) => (r.matching_digits === null ? 16 : r.matching_digits));
  /* The axis spans the data with a margin, not 0..max. Anchoring at zero left the lower half of
   * the chart empty and flattened the very shape the figure exists to show — and this is a count
   * of matching digits, where zero is not a meaningful baseline anyone reads against. */
  const lo = Math.floor(Math.min(...digits)) - 1;
  const hi = Math.ceil(Math.max(...digits)) + 1;
  const x = (i) => padL + (i / (sweep.length - 1)) * (w - padL - padR);
  const y = (v) => padT + ((hi - v) / (hi - lo)) * (h - padT - padB);

  const node = svg('svg', {
    viewBox: `0 0 ${w} ${h}`,
    class: 'fig sweepfig',
    role: 'img',
    'aria-label':
      'Matching decimal digits against nudge size: agreement rises, peaks, then falls again',
  });

  for (let g = 0; g <= 4; g += 1) {
    const v = lo + ((hi - lo) * g) / 4;
    node.append(
      svg('line', { x1: padL, x2: w - padR, y1: y(v), y2: y(v), class: 'gridline' }),
      svgText(padL - 10, y(v) + 4, 'axis end', v.toFixed(0))
    );
  }
  node.append(svgText(padL - 10, padT - 4, 'axis end', 'digits'));

  const d = digits.map((v, i) => `${i ? 'L' : 'M'} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');
  node.append(svg('path', { d, class: 'sweep-line' }));

  const best = digits.indexOf(Math.max(...digits));
  digits.forEach((v, i) => {
    node.append(
      svg('circle', { cx: x(i), cy: y(v), r: i === best ? 6 : 4, class: i === best ? 'dot best' : 'dot' })
    );
    node.append(svgText(x(i), h - padB + 20, 'axis mid', `1e${Math.round(Math.log10(sweep[i].epsilon))}`));
  });
  node.append(svgText(w / 2, h - 8, 'axis mid', 'nudge size'));
  /* Above the point, but inside the padding reserved for it — the first version put it 16px above
   * a peak that was already at the top of the plot, and it rendered clipped by the viewBox. */
  node.append(
    svgText(x(best), Math.max(y(digits[best]) - 16, 16), 'sweep-lab mid',
      `${digits[best].toFixed(1)} digits`)
  );
  node.append(svgText(padL + 4, y(digits[0]) + 22, 'sweep-side', 'too big: a straight line across a curve'));
  node.append(
    svgText(w - padR - 4, y(digits[digits.length - 1]) + 22, 'sweep-side end', 'too small: rounding noise')
  );

  return node;
}

function chapterResults(M) {
  const two = M.item_2_gradient;
  const three = M.item_3_accumulation;
  const four = M.item_4_grad_norm;
  const five = M.item_5_mfu;
  const six = M.item_6_floats;
  const curves = three.curves;

  const s = section(
    'results',
    'results',
    'What happened',
    'Six numbers, and the two that had to be corrected',
    [
      `Every figure below is read from <code>results/run.json</code>. Nothing on this page is typed,
       and a test regenerates the page's data and fails if the tracked copy differs.`,
    ],
    { short: 'What happened', sub: 'six numbers' }
  );

  s.append(
    figure(
      sweepFigure(M),
      2,
      `<b>The shape is the finding, not the peak.</b> A hand-computed derivative draws a straight
       line across a curve — the wider you draw it the less it matches — so agreement improves as
       the nudge shrinks. Then it gets <i>worse</i>, because the two losses being subtracted stop
       differing in bits the float type keeps. There is a <b>window</b>, not a best value, and a
       check that agreed at exactly one nudge size would have been fitted rather than verified.`
    )
  );

  s.append(
    table(
      ['measurement', 'result'],
      [
        {
          cells: [
            '1 · every shape in the step',
            'the loss has <b>no dimensions at all</b> — which is why a mistake anywhere before it changes training without changing a shape',
          ],
        },
        {
          cells: [
            '2 · one gradient, by hand',
            `autograd <b>${two.analytic.toFixed(9)}</b> against <b>${two.numeric.toFixed(9)}</b> — ${two.best_matching_digits.toFixed(1)} matching digits`,
          ],
        },
        {
          cells: [
            '3 · accumulation, broken',
            `<b>${three.correct.toFixed(4)}</b> correct against <b>${three.wrong.toFixed(4)}</b> wrong — ${pct(three.relative_gap)} out`,
          ],
        },
        {
          cells: [
            '4 · the grad norm leading',
            `<b>${four.count}</b> of ${int(M.facts.steps)} steps qualify`,
          ],
          __mark: 'warn',
        },
        {
          cells: [
            '5 · utilisation',
            `<b>${pct(five.mfu, 2)}</b> of ${(five.device_peak_flops / 1e12).toFixed(3)} TFLOP/s measured on this machine`,
          ],
        },
        {
          cells: [
            '6 · 0.1 in three formats',
            `fp32 <code>${six.fp32.hex}</code> · bf16 <code>${six.bf16.hex}</code> · fp8 E4M3 <code>${six['fp8 E4M3'].hex}</code>`,
          ],
        },
      ]
    )
  );

  const acc = el('p', 'say');
  acc.innerHTML = `<b>And the same two reductions driving a real run.</b> Over
    ${int(curves.total_steps)} steps, everything held identical but the reduction, the wrong one
    ends ${signed(curves.final_gap)} away. But the sign is not constant — it reads lower at
    <b>${curves.steps_where_wrong_read_lower}</b> of those steps — so the signed mean
    (${signed(curves.mean_signed_gap)}) is the number that carries a direction, and the endpoint
    alone would be whichever step the run happened to stop on.`;
  s.append(acc);

  const norm = el('p', 'say');
  norm.innerHTML = `<b>The gradient-norm result is the weakest thing on this page and is reported
    that way.</b> A step qualifies only if the norm moved sharply, the loss did not, <i>and</i> the
    loss then followed — the third condition is what makes it a claim about <i>before</i> rather
    than a same-step size comparison. ${four.count} of ${int(M.facts.steps)} steps clear that bar,
    and at the strictest threshold none do.`;
  s.append(norm);
}

